def rotate_matrix(matrix):
    if not matrix:
        return []
    rows = len(matrix)
    cols = len(matrix[0])
    if cols == 0:
        return []
    return [[matrix[rows - 1 - j][i] for j in range(rows)] for i in range(cols)]
